      beijing = 52810,
      card_cg_anim = "none",
      dialog = 3,
      music = "xm_15059_voice",
      renwu = "npc",
      sentence = "I watched the breeze stir the blossoms into a slow, drifting dance. Watched Lucien's every elegant gesture as he plucked the strings—each sending his unspoken thought far into the distance.",
      next = {25}
    },
    [25] = {
      beijing = 52810,
      card_cg_anim = "none",
      dialog = 3,
      music = "xm_15059_voice",
      renwu = "npc",
      sentence = "It felt like I saw everything in that instant.",
