      beijing = 52810,
      card_cg_anim = "none",
      dialog = 3,
      music = "xm_15059_voice",
      renwu = "npc",
      sentence = "The piece he played wasn't perfect. I'd heard fragments of it before during his practice—it seemed to be something composed by Professor Young himself.",
