    },
    [28] = {
      beijing = 52810,
      card_cg_anim = "none",
      dialog = 3,
      music = "xm_15059_voice",
      renwu = "npc",
      sentence = "But I knew—this wasn't about performance. He was simply bringing the melody to life, letting it mark the end of this chapter. A gentle farewell wrapped in song.",
