      music = "27_Double_Seventh",
      renwu = "npc",
      role1 = 2174000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2174404,
      sentence = "Lucien looked at me quietly. He didn't say anything for a moment. Maybe he knew that wasn't really a question.",
